        ar: "اَلْمُقَابَلَةُ تَحْتَاجُ إِجَابَاتٍ مُتَّصِلَةً لَا كَلِمَةً وَاحِدَةً 🎙️\n\n① اَلتَّعْرِيفُ بِالنَّفْسِ — ثَلَاثُ جُمَلٍ:\nاِسْمِي … · أَنَا مِنْ … · أَعْمَلُ / أَدْرُسُ …\n\n② «مُنْذُ» لِلْمُدَّةِ ⏳ وَمَا بَعْدَهَا مَجْرُورٌ:\nمُنْذُ سَنَتَيْنِ · مُنْذُ الصِّغَرِ\nمُنْذُ مَتَى؟ ← سُؤَالٌ عَنْ بِدَايَةِ الْمُدَّةِ\n\n③ اِرْبِطْ زَمَنَيْنِ فِي إِجَابَةٍ وَاحِدَةٍ:\nفِي الْمَاضِي ⏮️ كُنْتُ … وَحَالِيًّا ⏰ أَنَا …\nوَفِي الْمُسْتَقْبَلِ ⏭️ سَأَكُونُ …\n\n④ اَلْمُوَازَنَةُ بِـ «لَكِنَّ»:\nأَجِدُ صُعُوبَةً فِي … لَكِنِّي أَسْتَمْتِعُ بِـ …\n\n⚠️ «لَكِنَّ» + ضَمِيرٌ ← لَكِنَّنِي / لَكِنِّي\n\n⑤ «هَدَفِي أَنْ» + مُضَارِعٌ مَنْصُوبٌ:\nهَدَفِي أَنْ أَفْهَمَ الْقُرْآنَ 🎯\n(أَفْهَمُ ← أَفْهَمَ بَعْدَ أَنْ)",
